import React, { useState, useEffect } from 'react';

export default function App() {
  const [activeTab, setActiveTab] = useState('marketplace');
  const [listings, setListings] = useState([]);
  const [userCoins, setUserCoins] = useState(850);
  const [selectedListing, setSelectedListing] = useState(null);
  const [filters, setFilters] = useState({ category: 'All', action: 'All', search: '' });

  // Form State with Professional Brand & Model mapping
  const [formData, setFormData] = useState({
    title: '',
    category: 'Smartphones',
    brand: 'Apple',
    modelName: 'iPhone 14 Pro',
    condition: 'Like New',
    age: 1,
    actionType: 'Sell',
    imageUrl: 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=600&q=80'
  });

  const [estValue, setEstValue] = useState(0);

  // Model suggestions based on brand selection
  const brandModels = {
    Apple: ['iPhone 15 Pro Max', 'iPhone 14 Pro', 'iPhone 13', 'MacBook Pro M2', 'iPad Air'],
    Samsung: ['Galaxy S24 Ultra', 'Galaxy S23', 'Galaxy Z Flip5', 'Galaxy Tab S9'],
    OnePlus: ['OnePlus 12', 'OnePlus 11R', 'OnePlus Nord 3'],
    Dell: ['Dell XPS 15', 'Dell Inspiron 14', 'Dell Latitude'],
    HP: ['HP Pavilion', 'HP Envy x360', 'HP Spectre'],
    Sony: ['Sony Bravia 4K TV', 'Sony WH-1000XM5']
  };

  const modelsList = brandModels[formData.brand] || ['General Model'];

  // Fetch listings from backend
  useEffect(() => {
    fetch('http://localhost:5000/api/listings')
      .then(res => res.json())
      .then(data => {
        if (Array.isArray(data)) setListings(data);
      })
      .catch(err => console.log('Backend fetch error:', err));
  }, []);

  // Professional Valuation Formula
  useEffect(() => {
    let base = 20000;
    if (formData.category === 'Smartphones') base = 25000;
    else if (formData.category === 'Laptops') base = 45000;
    else if (formData.category === 'Televisions') base = 30000;

    let brandMultiplier = 1.0;
    if (formData.brand === 'Apple') brandMultiplier = 1.6;
    else if (formData.brand === 'Samsung') brandMultiplier = 1.3;
    else if (formData.brand === 'Dell' || formData.brand === 'HP') brandMultiplier = 1.2;
    else brandMultiplier = 0.9;

    let conditionFactor = 0.8;
    if (formData.condition === 'Like New') conditionFactor = 0.95;
    else if (formData.condition === 'Good') conditionFactor = 0.75;
    else if (formData.condition === 'Fair') conditionFactor = 0.5;
    else conditionFactor = 0.25;

    const ageDeduction = formData.age * 1800;
    const finalVal = Math.round((base * brandMultiplier * conditionFactor) - ageDeduction);
    setEstValue(Math.max(800, finalVal));
  }, [formData]);

  const handlePostAd = async (e) => {
    e.preventDefault();
    const coins = formData.actionType === 'Recycle' ? 300 : formData.actionType === 'Donate' ? 350 : 200;
    const newAd = {
      ...formData,
      title: `${formData.brand} ${formData.modelName}`,
      estimatedValue: estValue,
      status: 'Verified & Listed',
      greenCoins: coins
    };

    try {
      const response = await fetch('http://localhost:5000/api/listings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newAd)
      });
      const savedListing = await response.json();
      setListings([savedListing, ...listings]);
      setUserCoins(prev => prev + coins);
      alert(`Success! Listing published & +${coins} GreenCoins credited.`);
      setActiveTab('marketplace');
    } catch (err) {
      alert('Error connecting to backend database.');
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900 font-sans flex flex-col">
      {/* Flipkart / Amazon Style Professional Top Navigation Header */}
      <header className="bg-slate-900 text-white shadow-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-3 flex items-center justify-between gap-6">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={() => setActiveTab('marketplace')}>
            <div className="bg-gradient-to-tr from-amber-400 to-orange-500 text-slate-950 p-2.5 rounded-xl font-black text-xl tracking-wider shadow">
              RX
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-lg font-black tracking-wide text-white">ReCircuit <span className="text-amber-400">X</span></h1>
                <span className="text-[10px] bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 px-2 py-0.5 rounded-full font-semibold">PRO VIVA EDITION</span>
              </div>
              <p className="text-xs text-slate-400">AI-Powered Circular E-Commerce & Valuation Hub</p>
            </div>
          </div>

          {/* Search Bar */}
          <div className="flex-1 max-w-xl hidden md:block">
            <div className="relative">
              <input 
                type="text" 
                placeholder="Search refurbished phones, laptops, eco-gadgets..." 
                className="w-full bg-slate-800 text-white placeholder-slate-400 text-sm rounded-xl pl-4 pr-10 py-2.5 border border-slate-700 focus:outline-none focus:border-amber-400 transition shadow-inner"
                onChange={e => setFilters({...filters, search: e.target.value})}
              />
              <span className="absolute right-3 top-2.5 text-slate-400 text-sm">🔍</span>
            </div>
          </div>

          {/* User Stats & Wallet */}
          <div className="flex items-center gap-4">
            <div className="bg-slate-800 border border-slate-700 px-3.5 py-1.5 rounded-xl flex items-center gap-2 shadow-sm">
              <span className="text-amber-400 font-bold text-base">🪙</span>
              <div>
                <p className="text-[10px] text-slate-400 uppercase tracking-wider font-semibold">GreenCoins</p>
                <p className="text-xs font-black text-amber-300">{userCoins} Coins</p>
              </div>
            </div>
            <div className="hidden lg:flex bg-emerald-950/60 border border-emerald-800 px-3.5 py-1.5 rounded-xl items-center gap-2">
              <span className="text-emerald-400">🌱</span>
              <div>
                <p className="text-[10px] text-emerald-300 uppercase tracking-wider font-semibold">CO₂ Offset</p>
                <p className="text-xs font-black text-emerald-200">54.2 kg</p>
              </div>
            </div>
          </div>
        </div>

        {/* E-Commerce Category Sub-bar */}
        <nav className="bg-slate-800/90 backdrop-blur border-t border-slate-700 px-6 flex gap-6 overflow-x-auto text-sm">
          {[
            { id: 'marketplace', label: '🛍️ Live Marketplace' },
            { id: 'post', label: '⚡ Valuation & Post Ad' },
            { id: 'dashboard', label: '📊 Impact Dashboard' },
            { id: 'erasure', label: '🛡️ Data Sanitation Cert' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`py-3 font-semibold transition whitespace-nowrap border-b-2 ${activeTab === tab.id ? 'border-amber-400 text-amber-400' : 'border-transparent text-slate-300 hover:text-white'}`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </header>

      {/* Main Container */}
      <main className="max-w-7xl mx-auto px-6 py-8 flex-1 w-full">
        {activeTab === 'marketplace' && (
          <div className="space-y-6">
            {/* Filters Header */}
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 flex flex-wrap gap-4 items-center justify-between">
              <div className="flex items-center gap-3">
                <h2 className="font-bold text-slate-800 text-base">Available E-Waste & Refurbished Inventory</h2>
                <span className="bg-slate-100 text-slate-600 px-2.5 py-0.5 rounded-full text-xs font-semibold">{listings.length} items live</span>
              </div>
              <div className="flex flex-wrap gap-3">
                <select className="border border-slate-200 rounded-xl px-3 py-2 text-xs bg-slate-50 font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-amber-400" onChange={e => setFilters({...filters, category: e.target.value})}>
                  <option value="All">All Categories</option>
                  <option value="Smartphones">Smartphones</option>
                  <option value="Laptops">Laptops</option>
                  <option value="Televisions">Televisions</option>
                </select>
                <select className="border border-slate-200 rounded-xl px-3 py-2 text-xs bg-slate-50 font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-amber-400" onChange={e => setFilters({...filters, action: e.target.value})}>
                  <option value="All">All Action Types (Sell/Donate/Recycle)</option>
                  <option value="Sell">Sell (Marketplace)</option>
                  <option value="Donate">Donate (NGO)</option>
                  <option value="Recycle">Recycle (Eco-Hub)</option>
                </select>
              </div>
            </div>

            {/* E-Commerce Product Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {listings
                .filter(l => (filters.category === 'All' || l.category === filters.category) && 
                             (filters.action === 'All' || l.actionType === filters.action) &&
                             (l.title.toLowerCase().includes(filters.search.toLowerCase()) || l.brand?.toLowerCase().includes(filters.search.toLowerCase())))
                .map(item => (
                <div key={item._id || item.id} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex flex-col hover:shadow-xl hover:border-amber-400 transition duration-300 group">
                  <div className="relative h-52 bg-slate-100 overflow-hidden">
                    <img src={item.imageUrl} alt={item.title} className="w-full h-full object-cover group-hover:scale-105 transition duration-500" />
                    <span className="absolute top-3 right-3 bg-amber-400 text-slate-950 text-xs font-black px-3 py-1 rounded-full shadow-md uppercase tracking-wider">
                      {item.actionType}
                    </span>
                    <span className="absolute bottom-3 left-3 bg-slate-900/80 backdrop-blur text-white text-[11px] font-medium px-3 py-1 rounded-lg">
                      Status: {item.status}
                    </span>
                  </div>

                  <div className="p-5 flex-1 flex flex-col justify-between space-y-4">
                    <div>
                      <div className="flex justify-between items-start">
                        <h3 className="font-bold text-slate-900 text-base line-clamp-1">{item.title}</h3>
                        <span className="text-emerald-700 font-black text-lg">₹{item.estimatedValue}</span>
                      </div>
                      <p className="text-xs text-slate-500 mt-1 font-medium">{item.brand} • {item.condition} • {item.age} yrs old</p>
                    </div>

                    <div className="pt-3 border-t border-slate-100 flex justify-between items-center">
                      <span className="text-xs font-bold text-amber-600 bg-amber-50 px-2.5 py-1 rounded-lg border border-amber-200">
                        🪙 +{item.greenCoins} Coins
                      </span>
                      <button onClick={() => setSelectedListing(item)} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-amber-400 hover:text-slate-950 transition shadow">
                        View Details & Route
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'post' && (
          <div className="max-w-3xl mx-auto bg-white p-8 rounded-3xl shadow-md border border-slate-200">
            <div className="border-b pb-4 mb-6">
              <h2 className="text-2xl font-black text-slate-900">Post Device & AI Valuation Engine</h2>
              <p className="text-sm text-slate-500 mt-1">Configure brand specifications, age, and condition to calculate precise residual e-waste value.</p>
            </div>

            <form onSubmit={handlePostAd} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-slate-700 mb-2">Device Category</label>
                  <select className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm bg-slate-50 font-semibold focus:outline-none focus:ring-2 focus:ring-amber-400" onChange={e => setFormData({...formData, category: e.target.value})}>
                    <option value="Smartphones">📱 Smartphones</option>
                    <option value="Laptops">💻 Laptops & Notebooks</option>
                    <option value="Televisions">📺 Televisions & Displays</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-slate-700 mb-2">Select Brand / Company</label>
                  <select className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm bg-slate-50 font-semibold focus:outline-none focus:ring-2 focus:ring-amber-400" value={formData.brand} onChange={e => {
                    const newBrand = e.target.value;
                    setFormData({...formData, brand: newBrand, modelName: brandModels[newBrand]?.[0] || 'Standard Model'});
                  }}>
                    <option value="Apple"> Apple (High Resale Holding)</option>
                    <option value="Samsung">📱 Samsung (Flagship Tier)</option>
                    <option value="OnePlus">⚡ OnePlus</option>
                    <option value="Dell">💻 Dell</option>
                    <option value="HP">💻 HP</option>
                    <option value="Sony">📺 Sony</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold uppercase tracking-wider text-slate-700 mb-2">Specific Model Name</label>
                <select className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm bg-slate-50 font-semibold focus:outline-none focus:ring-2 focus:ring-amber-400" value={formData.modelName} onChange={e => setFormData({...formData, modelName: e.target.value})}>
                  {modelsList.map((model, idx) => (
                    <option key={idx} value={model}>{model}</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-slate-700 mb-2">Physical Condition</label>
                  <select className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm bg-slate-50 font-semibold focus:outline-none focus:ring-2 focus:ring-amber-400" onChange={e => setFormData({...formData, condition: e.target.value})}>
                    <option value="Like New">✨ Like New (95% Value Retention)</option>
                    <option value="Good">👍 Good (75% Value Retention)</option>
                    <option value="Fair">⚠️ Fair (50% Value Retention)</option>
                    <option value="Non-Working">♻️ Non-Working / Dead (Scrap Base)</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold uppercase tracking-wider text-slate-700 mb-2">Action Preference</label>
                  <select className="w-full border border-slate-300 rounded-xl px-4 py-3 text-sm bg-slate-50 font-semibold focus:outline-none focus:ring-2 focus:ring-amber-400" onChange={e => setFormData({...formData, actionType: e.target.value})}>
                    <option value="Sell">🛍️ Sell on Marketplace</option>
                    <option value="Donate">🤝 Donate to Partner NGO</option>
                    <option value="Recycle">♻️ Send to Certified Recycler</option>
                  </select>
                </div>
              </div>

              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="text-xs font-bold uppercase tracking-wider text-slate-700">Device Age (Years Used)</label>
                  <span className="text-sm font-black text-amber-600 bg-amber-50 px-3 py-0.5 rounded-lg border border-amber-200">{formData.age} Years (₹1800/yr depreciation)</span>
                </div>
                <input type="range" min="0" max="8" value={formData.age} className="w-full accent-amber-500 h-2 bg-slate-200 rounded-lg cursor-pointer" onChange={e => setFormData({...formData, age: Number(e.target.value)})} />
              </div>

              {/* Dynamic Valuation Summary Box */}
              <div className="bg-gradient-to-r from-slate-900 to-slate-800 text-white p-6 rounded-2xl flex items-center justify-between shadow-lg">
                <div>
                  <span className="bg-amber-400 text-slate-950 text-[10px] font-black px-2.5 py-1 rounded uppercase tracking-wider">Brand-Weighted Formula Active</span>
                  <h4 className="text-sm text-slate-300 mt-2 font-medium">Estimated Residual Valuation</h4>
                </div>
                <div className="text-3xl font-black text-amber-400">₹{estValue}</div>
              </div>

              <button type="submit" className="w-full bg-amber-400 text-slate-950 py-4 rounded-xl font-black hover:bg-amber-300 transition shadow-md text-base tracking-wide">
                Publish Listing to Cloud Database 🚀
              </button>
            </form>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-4">
                <div className="p-4 bg-amber-100 text-amber-700 rounded-2xl text-2xl font-black">🪙</div>
                <div>
                  <p className="text-xs text-slate-500 font-bold uppercase">Total GreenCoins</p>
                  <h3 className="text-2xl font-black text-slate-900">{userCoins} Coins</h3>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-4">
                <div className="p-4 bg-emerald-100 text-emerald-700 rounded-2xl text-2xl font-black">🌱</div>
                <div>
                  <p className="text-xs text-slate-500 font-bold uppercase">Carbon Saved</p>
                  <h3 className="text-2xl font-black text-slate-900">54.2 kg</h3>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex items-center gap-4">
                <div className="p-4 bg-sky-100 text-sky-700 rounded-2xl text-2xl font-black">♻️</div>
                <div>
                  <p className="text-xs text-slate-500 font-bold uppercase">Circulated Units</p>
                  <h3 className="text-2xl font-black text-slate-900">4 Devices</h3>
                </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'erasure' && (
          <div className="max-w-2xl mx-auto bg-white p-8 rounded-3xl shadow-md border border-slate-200 space-y-6">
            <div>
              <h2 className="text-2xl font-black text-slate-900">NIST SP 800-88 Data Sanitization</h2>
              <p className="text-sm text-slate-500 mt-1">Generate verified cryptographic erasure certificates for corporate and personal electronics disposal.</p>
            </div>
            <div className="p-6 bg-slate-900 text-white rounded-2xl space-y-4">
              <div className="flex justify-between items-center border-b border-slate-800 pb-3">
                <h3 className="font-bold text-amber-400">Digital Erasure Protocol</h3>
                <span className="bg-emerald-500 text-slate-950 font-bold px-2.5 py-0.5 rounded text-xs">READY</span>
              </div>
              <p className="text-xs text-slate-300">Ensures 100% permanent removal of personal files, cache, and OS tokens before recycling or resale.</p>
              <button onClick={() => alert('Certificate generated & verified successfully!')} className="w-full bg-amber-400 text-slate-950 py-3 rounded-xl font-bold text-sm hover:bg-amber-300 transition">
                Generate Verified Certificate PDF
              </button>
            </div>
          </div>
        )}
      </main>

      {selectedListing && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-3xl max-w-md w-full p-6 space-y-6 shadow-2xl border border-slate-200">
            <div className="flex justify-between items-center border-b pb-4">
              <h3 className="font-bold text-lg text-slate-900">Action Route: {selectedListing.actionType}</h3>
              <button onClick={() => setSelectedListing(null)} className="text-slate-400 hover:text-slate-600 font-bold text-lg">✕</button>
            </div>

            <div className="space-y-4">
              <div className="flex gap-4 items-center bg-slate-50 p-3 rounded-2xl border border-slate-100">
                <img src={selectedListing.imageUrl} alt="" className="w-16 h-16 object-cover rounded-xl" />
                <div>
                  <h4 className="font-bold text-slate-900 text-sm">{selectedListing.title}</h4>
                  <p className="text-xs text-slate-500">Valued at: <span className="font-bold text-emerald-700">₹{selectedListing.estimatedValue}</span></p>
                </div>
              </div>

              <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-200 text-xs text-emerald-900 space-y-2">
                <p className="font-bold">✅ Verification Status</p>
                <p>This item is authenticated via ReCircuit X valuation engine and ready for secure routing.</p>
              </div>

              <button onClick={() => { alert('Action successfully executed!'); setSelectedListing(null); }} className="w-full bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-amber-400 hover:text-slate-950 transition">
                Confirm & Proceed
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
